{"path": "/tmp/sv-4007d81bd6d44b4ca730ddd018d4775c/Components/Pages/Board/AddTaskForm.razor", "file_text": "<div class="add-task-form">
    <div class="form-group">
        <input type="text" class="form-control" placeholder="Title" @bind="title" />
    </div>
    <div class="form-group">
        <input type="text" class="form-control" placeholder="Assignee" @bind="assignee" />
    </div>
    <div class="form-group">
        <select class="form-control" @bind="priority">
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
        </select>
    </div>
    <div class="form-group">
        <input type="date" class="form-control" @bind="dueDate" />
    </div>
    <div class="form-actions">
        <button class="btn btn-primary btn-sm" @onclick="Save">Save</button>
        <button class="btn btn-secondary btn-sm" @onclick="Cancel">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public string Status { get; set; } = default!;

    [Parameter]
    public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnSave { get; set; }

    [Parameter]
    public EventCallback OnCancel { get; set; }

    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);

    private async Task Save()
    {
        if (!string.IsNullOrWhiteSpace(title) && !string.IsNullOrWhiteSpace(assignee))
        {
            await OnSave.InvokeAsync((title, assignee, priority, dueDate));
            title = string.Empty;
            assignee = string.Empty;
            priority = "Medium";
            dueDate = DateTime.Today.AddDays(7);
        }
    }

    private async Task Cancel() => await OnCancel.InvokeAsync();
}
"}

{"path": "/tmp/sv-4007d81bd6d44b4ca730ddd018d4775c/Components/Pages/Board/BoardColumn.razor", "file_text": "<div class="board-column">
    <div class="board-column-header">
        <h3>@Title <span class="task-count">(@Tasks.Count)</span></h3>
    </div>
    <div class="board-column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      OnMoveLeft="OnMoveLeft"
                      OnMoveRight="OnMoveRight" />
        }
    </div>
    <div class="board-column-footer">
        @if (showAddForm)
        {
            <AddTaskForm Status="@Status"
                         OnSave="HandleSave"
                         OnCancel="HandleCancel" />
        }
        else
        {
            <button class="btn btn-add-task" @onclick="() => showAddForm = true">+ Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public string Title { get; set; } = default!;

    [Parameter, EditorRequired]
    public string Status { get; set; } = default!;

    [Parameter]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public bool ShowMoveLeft { get; set; }

    [Parameter]
    public bool ShowMoveRight { get; set; }

    [Parameter]
    public EventCallback<int> OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback<int> OnMoveRight { get; set; }

    [Parameter]
    public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnAddTask { get; set; }

    private bool showAddForm;

    private async Task HandleSave((string Title, string Assignee, string Priority, DateTime DueDate) newTask)
    {
        await OnAddTask.InvokeAsync(newTask);
        showAddForm = false;
    }

    private void HandleCancel() => showAddForm = false;
}
"}

