@page "/board"
@using sv_4007d81bd6d44b4ca730ddd018d4775c.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (isLoading)
{
    <p class="loading-message">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <div class="error-message">
        <p>@errorMessage</p>
        <button class="btn btn-primary" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStats Total="@allTasks.Count"
                TodoCount="@TodoTasks.Count"
                InProgressCount="@InProgressTasks.Count"
                DoneCount="@DoneTasks.Count"
                OverdueCount="@OverdueCount" />

    <BoardSearchBar SearchText="@searchText" SearchTextChanged="OnSearchChanged" />

    <div class="board-columns">
        <BoardColumn Title="To Do"
                     Status="To Do"
                     Tasks="TodoTasks"
                     ShowMoveLeft="false"
                     ShowMoveRight="true"
                     OnMoveRight="MoveRight"
                     OnAddTask="args => AddTask(args, \"To Do\")" />

        <BoardColumn Title="In Progress"
                     Status="In Progress"
                     Tasks="InProgressTasks"
                     ShowMoveLeft="true"
                     ShowMoveRight="true"
                     OnMoveLeft="MoveLeft"
                     OnMoveRight="MoveRight"
                     OnAddTask="args => AddTask(args, \"In Progress\")" />

        <BoardColumn Title="Done"
                     Status="Done"
                     Tasks="DoneTasks"
                     ShowMoveLeft="true"
                     ShowMoveRight="false"
                     OnMoveLeft="MoveLeft"
                     OnAddTask="args => AddTask(args, \"Done\")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] Statuses = ["To Do", "In Progress", "Done"];

    private List<TaskItem> FilteredTasks => string.IsNullOrWhiteSpace(searchText)
        ? allTasks
        : allTasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();

    private List<TaskItem> TodoTasks => FilteredTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> InProgressTasks => FilteredTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> DoneTasks => FilteredTasks.Where(t => t.Status == "Done").ToList();
    private int OverdueCount => allTasks.Count(t => t.DueDate < DateTime.Today);

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void OnSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task MoveLeft(int taskId)
    {
        var task = allTasks.FirstOrDefault(t => t.Id == taskId);
        if (task is null) return;

        var currentIndex = Array.IndexOf(Statuses, task.Status);
        if (currentIndex <= 0) return;

        var newStatus = Statuses[currentIndex - 1];
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var idx = allTasks.FindIndex(t => t.Id == taskId);
            allTasks[idx] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task MoveRight(int taskId)
    {
        var task = allTasks.FirstOrDefault(t => t.Id == taskId);
        if (task is null) return;

        var currentIndex = Array.IndexOf(Statuses, task.Status);
        if (currentIndex >= Statuses.Length - 1) return;

        var newStatus = Statuses[currentIndex + 1];
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var idx = allTasks.FindIndex(t => t.Id == taskId);
            allTasks[idx] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task AddTask((string Title, string Assignee, string Priority, DateTime DueDate) newTask, string status)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(newTask.Title, newTask.Assignee, newTask.Priority, newTask.DueDate);
            allTasks.Add(created);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

